-- Generated by scripts/feature-post.mjs. Makes "sprinkler-blowout-assigned-week-default-yes" the featured Industry LoogoBlog
-- post. Clear first, then set, so posts_one_featured never sees two rows.
UPDATE "posts" SET "featured" = false WHERE "featured" AND "slug" <> 'sprinkler-blowout-assigned-week-default-yes';
UPDATE "posts" SET "featured" = true WHERE "slug" = 'sprinkler-blowout-assigned-week-default-yes' AND "status" = 'published';
